/**
 * Frontend types for the engin web interface.
 *
 * Mirrors the backend protocol types from src/web/types.ts (T02) but
 * does NOT import from the backend.  The additional frontend-specific
 * types (WorkflowRunState, AppGlobalState) manage UI state client-side.
 */

// ─── Shared value types (mirrored from T02) ─────────────────────────────────

export interface PhaseDescriptor {
  id: string;
  label: string;
  icon: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  type:
    | 'text'
    | 'thinking'
    | 'tool_call'
    | 'tool_call_start'
    | 'tool_call_end'
    | 'decision'
    | 'error';
  content: string;
  metadata?: Record<string, unknown>;
}

export interface AgentWindowState {
  agentId: string;
  profile: string;
  taskId?: string;
  active: boolean;
  log: LogEntry[];
}

export interface SidebarInfo {
  title: string;
  indicator: string;
  phases?: PhaseDescriptor[];
}

export interface WorkflowSummary {
  id: string;
  workflowName: string;
  status: 'running' | 'completed' | 'failed';
  sidebar: SidebarInfo;
  startedAt: string;
  completedAt?: string;
}

// ─── Server → Client messages (mirrored from T02) ───────────────────────────

export type ServerMessage =
  | { type: 'init'; workflows: WorkflowSummary[] }
  | { type: 'workflow_started'; summary: WorkflowSummary }
  | { type: 'workflow_sidebar'; workflowId: string; sidebar: SidebarInfo }
  | { type: 'workflow_phase'; workflowId: string; phase: string; completed: string[] }
  | { type: 'workflow_complete'; summary: WorkflowSummary }
  | { type: 'workflow_failed'; summary: WorkflowSummary; error: string; phase: string }
  | { type: 'agent_spawned'; workflowId: string; agent: AgentWindowState }
  | { type: 'agent_log'; workflowId: string; agentId: string; entry: LogEntry }
  | { type: 'agent_complete'; workflowId: string; agentId: string };

// ─── Client → Server messages (mirrored from T02) ───────────────────────────

export type ClientMessage =
  | { type: 'start_workflow'; workflowName: string; taskPrompt: string; maxConcurrent?: number }
  | { type: 'select_workflow'; workflowId: string }
  | { type: 'cancel_workflow'; workflowId: string };

// ─── Frontend-specific state types ──────────────────────────────────────────

export interface WorkflowRunState {
  summary: WorkflowSummary;
  agents: Map<string, AgentWindowState>;
  currentPhase: string;
  completedPhases: string[];
}

export interface AppGlobalState {
  workflows: WorkflowSummary[];
  selectedRunId: string | null;
  runStates: Map<string, WorkflowRunState>;
}

// ─── Type guard ─────────────────────────────────────────────────────────────

export function isServerMessage(data: unknown): data is ServerMessage {
  return typeof data === 'object' && data !== null && 'type' in data;
}

import { useEffect, useRef, useState, useCallback } from 'react';
import type { AppGlobalState, ClientMessage, ServerMessage } from '../types';
import { isServerMessage } from '../types';

export function useWebSocket() {
  const [state, setState] = useState<AppGlobalState>({
    workflows: [],
    selectedRunId: null,
    runStates: new Map(),
  });

  const [connected, setConnected] = useState(false);

  const wsRef = useRef<WebSocket | null>(null);
  const stateRef = useRef(state);
  stateRef.current = state;

  const reconnectTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const connect = useCallback(() => {
    // Determine WS URL
    const wsEndpoint =
      (typeof window !== 'undefined' && (window as any).__WS_ENDPOINT__) ||
      'ws://localhost:3619/ws';

    const ws = new WebSocket(wsEndpoint);
    wsRef.current = ws;

    ws.onopen = () => {
      console.log('WebSocket connected');
      setConnected(true);
    };

    ws.onmessage = (event: MessageEvent) => {
      try {
        const data: unknown = JSON.parse(event.data as string);
        if (!isServerMessage(data)) {
          console.warn('Received invalid message from server', data);
          return;
        }
        handleServerMessage(data);
      } catch (err) {
        console.error('Failed to parse WebSocket message', err);
      }
    };

    ws.onerror = (error: Event) => {
      console.error('WebSocket error', error);
    };

    ws.onclose = () => {
      setConnected(false);
      console.log('WebSocket disconnected, reconnecting in 3s...');
      reconnectTimeoutRef.current = setTimeout(() => {
        connect();
      }, 3000);
    };
  }, []);

  function handleServerMessage(msg: ServerMessage) {
    switch (msg.type) {
      case 'init': {
        setState((prev) => ({
          ...prev,
          workflows: msg.workflows,
        }));
        break;
      }
      case 'workflow_started': {
        setState((prev) => ({
          ...prev,
          workflows: [...prev.workflows, msg.summary],
          runStates: new Map(prev.runStates).set(msg.summary.id, {
            summary: msg.summary,
            agents: new Map(),
            currentPhase: '',
            completedPhases: [],
          }),
        }));
        break;
      }
      case 'workflow_sidebar': {
        setState((prev) => ({
          ...prev,
          workflows: prev.workflows.map((w) =>
            w.id === msg.workflowId ? { ...w, sidebar: msg.sidebar } : w
          ),
        }));
        break;
      }
      case 'workflow_phase': {
        setState((prev) => {
          const runStates = new Map(prev.runStates);
          const existing = runStates.get(msg.workflowId);
          if (existing) {
            runStates.set(msg.workflowId, {
              ...existing,
              currentPhase: msg.phase,
              completedPhases: msg.completed,
            });
          }
          return { ...prev, runStates };
        });
        break;
      }
      case 'workflow_complete': {
        setState((prev) => ({
          ...prev,
          workflows: prev.workflows.map((w) =>
            w.id === msg.summary.id
              ? { ...w, status: msg.summary.status, completedAt: msg.summary.completedAt }
              : w
          ),
        }));
        break;
      }
      case 'workflow_failed': {
        setState((prev) => ({
          ...prev,
          workflows: prev.workflows.map((w) =>
            w.id === msg.summary.id
              ? { ...w, status: msg.summary.status, completedAt: msg.summary.completedAt }
              : w
          ),
        }));
        break;
      }
      case 'agent_spawned': {
        setState((prev) => {
          const runStates = new Map(prev.runStates);
          const existing = runStates.get(msg.workflowId);
          if (existing) {
            const agents = new Map(existing.agents);
            agents.set(msg.agent.agentId, msg.agent);
            runStates.set(msg.workflowId, { ...existing, agents });
          } else {
            // Create new run state if not exists
            const workflow = prev.workflows.find((w) => w.id === msg.workflowId);
            runStates.set(msg.workflowId, {
              summary: workflow!,
              agents: new Map([[msg.agent.agentId, msg.agent]]),
              currentPhase: '',
              completedPhases: [],
            });
          }
          return { ...prev, runStates };
        });
        break;
      }
      case 'agent_log': {
        setState((prev) => {
          const runStates = new Map(prev.runStates);
          const runState = runStates.get(msg.workflowId);
          if (runState) {
            const agents = new Map(runState.agents);
            const agent = agents.get(msg.agentId);
            if (agent) {
              agents.set(msg.agentId, {
                ...agent,
                log: [...agent.log, msg.entry],
              });
            }
            runStates.set(msg.workflowId, { ...runState, agents });
          }
          return { ...prev, runStates };
        });
        break;
      }
      case 'agent_complete': {
        setState((prev) => {
          const runStates = new Map(prev.runStates);
          const runState = runStates.get(msg.workflowId);
          if (runState) {
            const agents = new Map(runState.agents);
            const agent = agents.get(msg.agentId);
            if (agent) {
              agents.set(msg.agentId, { ...agent, active: false });
            }
            runStates.set(msg.workflowId, { ...runState, agents });
          }
          return { ...prev, runStates };
        });
        break;
      }
      default:
        // Exhaustiveness check for compile-time safety
        const _exhaustive: never = msg;
        console.warn('Unhandled server message type', _exhaustive);
    }
  }

  const send = useCallback((msg: ClientMessage) => {
    wsRef.current?.send(JSON.stringify(msg));
  }, []);

  const selectRun = useCallback(
    (runId: string) => {
      setState((prev) => ({ ...prev, selectedRunId: runId }));
      send({ type: 'select_workflow', workflowId: runId });
    },
    [send]
  );

  useEffect(() => {
    connect();

    return () => {
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current);
      }
      wsRef.current?.close();
      wsRef.current = null;
    };
  }, [connect]);

  return { state, send, selectRun, connected };
}

import type { ComponentType } from 'react';
import type { WorkflowRendererProps } from './types';

const registry = new Map<string, ComponentType<WorkflowRendererProps>>();

export function registerRenderer(
  name: string,
  comp: ComponentType<WorkflowRendererProps>,
): void {
  registry.set(name, comp);
}

export function getRenderer(
  name: string,
): ComponentType<WorkflowRendererProps> | undefined {
  return registry.get(name);
}

import type { WorkflowRunState } from '../types';

export interface WorkflowRendererProps {
  runState: WorkflowRunState;
}

/**
 * DevelopRenderer — top-level renderer for "develop" workflows.
 *
 * Composes the horizontal ProgressIndicator (phase bar) with an AgentGrid
 * showing per-agent log panels.  A small label in .develop-content shows
 * the current (active) phase name.
 */

import type { WorkflowRendererProps } from '../types';
import { registerRenderer } from '../registry';
import { buildDevelopState } from './types';
import { ProgressIndicator } from './ProgressIndicator';
import { AgentGrid } from './AgentGrid';
import './DevelopRenderer.css';

export function DevelopRenderer({ runState }: WorkflowRendererProps) {
  const state = buildDevelopState(runState);

  return (
    <div className="develop-renderer">
      <ProgressIndicator phases={state.phases} />
      <div className="develop-content">
        {state.currentPhase && (
          <div className="develop-phase-label">{state.currentPhase}</div>
        )}
        <AgentGrid agents={state.agents} />
      </div>
    </div>
  );
}

registerRenderer('develop', DevelopRenderer);

import './Header.css';

interface HeaderProps {
  connected: boolean;
}

export function Header({ connected }: HeaderProps) {
  return (
    <header className="header">
      <span className="logo">engin</span>
      <span
        className="connection-dot"
        style={{ backgroundColor: connected ? 'var(--engin-success)' : 'var(--engin-error)' }}
      />
    </header>
  );
}

import './Sidebar.css';

import type { WorkflowSummary } from '../types';

interface SidebarProps {
  workflows: WorkflowSummary[];
  selectedRunId: string | null;
  onSelectRun: (runId: string) => void;
}

/**
 * Returns a human-readable relative time string.
 *
 * - < 60s: "just now"
 * - < 60m: "Xm ago"
 * - < 24h: "Xh ago"
 * - else:  "Xd ago"
 */
function relativeTime(iso: string): string {
  const now = Date.now();
  const then = new Date(iso).getTime();
  const diffSec = Math.floor((now - then) / 1000);

  if (diffSec < 60) return 'just now';
  if (diffSec < 3600) return `${Math.floor(diffSec / 60)}m ago`;
  if (diffSec < 86400) return `${Math.floor(diffSec / 3600)}h ago`;
  return `${Math.floor(diffSec / 86400)}d ago`;
}

const ACTIVE_LABEL = 'Active';
const PAST_LABEL = 'Past';

export function Sidebar({ workflows, selectedRunId, onSelectRun }: SidebarProps) {
  const active = workflows.filter((w) => w.status === 'running');
  const past = workflows.filter((w) => w.status !== 'running');

  const renderItem = (workflow: WorkflowSummary) => {
    const isSelected = workflow.id === selectedRunId;
    const statusClass =
      workflow.status === 'running'
        ? 'running'
        : workflow.status === 'completed'
          ? 'completed'
          : 'failed';

    return (
      <div
        key={workflow.id}
        className={`sidebar-item${isSelected ? ' selected' : ''} ${statusClass}`}
        onClick={() => onSelectRun(workflow.id)}
      >
        <span className={`sidebar-indicator${workflow.status === 'running' ? ' pulsing' : ''}`}>
          {workflow.sidebar.indicator}
        </span>
        <span className="sidebar-title">{workflow.sidebar.title}</span>
        <span className="sidebar-time">{relativeTime(workflow.startedAt)}</span>
      </div>
    );
  };

  return (
    <aside className="sidebar">
      <div className="sidebar-header">
        <span className="sidebar-header-text">Workflows</span>
      </div>

      {active.length > 0 && (
        <div className="sidebar-section">
          <span className="sidebar-section-title">{ACTIVE_LABEL}</span>
          {active.map(renderItem)}
        </div>
      )}

      {past.length > 0 && (
        <div className="sidebar-section">
          <span className="sidebar-section-title">{PAST_LABEL}</span>
          {past.map(renderItem)}
        </div>
      )}
    </aside>
  );
}

